import { Link, Outlet, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/useAuth';

export default function MainLayout() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  return (
    <div>
      <nav className="navbar navbar-expand navbar-dark bg-dark">
        <div className="container-fluid">
          <Link className="navbar-brand" to="/dashboard">CU Campus</Link>
          <div className="navbar-nav">
            <Link className="nav-link" to="/complaints">Complaints</Link>
            <Link className="nav-link" to="/gatepass">Gate Pass</Link>
            <Link className="nav-link" to="/mess">Mess</Link>
            <Link className="nav-link" to="/food">Food</Link>
            <Link className="nav-link" to="/profile">Profile</Link>
          </div>
          <div className="d-flex align-items-center gap-2 text-white">
            <span className="small">{user ? user.username : ''}</span>
            <button
              className="btn btn-outline-light btn-sm"
              onClick={() => {
                logout();
                navigate('/login');
              }}
            >
              Logout
            </button>
          </div>
        </div>
      </nav>

      <main className="container mt-4">
        <Outlet />
      </main>
    </div>
  );
}
